SELECT 'Writing Job Descriptions That Attract the Right People', 'A free, SME-focused introduction to writing Job Descriptions That Attract the Right People.', 'This free course walks you through writing Job Descriptions That Attract the Right People with real frameworks, templates, and examples built for small and medium business teams — not generic corporate theory.', '["Apply core hr techniques used by high-performing SME teams.","Avoid the most common mistakes SMEs make in this area.","Build practical templates and checklists you can use immediately.","Confidently explain the value of this approach to your stakeholders."]', '{"Is this course relevant if I\'m not in a formal HR role?":"Yes — anyone who hires, manages, or works with people benefits from these frameworks, not just HR specialists.","Does this align with local labor law?":"This course covers universal best practices in people management. Always verify specific policies against your local labor regulations.","How is this course assessed?":"Progress is tracked lesson by lesson, with practical templates you apply directly to your own team."}', 'English', (SELECT id FROM (SELECT id FROM `category` WHERE `slug` = 'hr') AS t1), (SELECT id FROM (SELECT id FROM `category` WHERE `slug` = 'recruitment-talent-acquisition') AS t2), '', '["No prior experience necessary.","A willingness to learn and apply new frameworks."]', 0, 0, NULL, 'beginner', (SELECT id FROM (SELECT id FROM `users` WHERE `email` = 'priya.nathan@gpli.io') AS t3), NULL, NULL, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 'general', 1, 0, 'active', NULL, 'HR, GPLI, free SME training', 'Learn writing Job Descriptions That Attract the Right People for free with GP Leadership Institute.', 1, 0, 0, (SELECT id FROM (SELECT id FROM `users` WHERE `email` = 'priya.nathan@gpli.io') AS t4), NULL
WHERE NOT EXISTS (SELECT 1 FROM `course` WHERE `title` = 'Writing Job Descriptions That Attract the Right People');

